// Pega o CSV como texto vindo do HTTP Request

const csvRaw = $json.data ?? $json.body ?? $json;

const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);



const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

const headers = lines[0].split(",").map(h => h.trim());



const investimentos = lines.slice(1).map(line => {

  const cols = line.split(",").map(c => c.trim());

  const obj = {};

  headers.forEach((h, i) => obj[h] = cols[i] ?? "");



  // normaliza mínimo para número

  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;



  return obj;

});



return [{ json: { investimentos } }];

// ================== CONFIG ==================
// 'por_investidor' -> 1 item por cliente (a IA gera 1 mensagem para cada)
// 'unico'          -> 1 item só com todos os clientes
const MODO = 'por_investidor';

// ================== HELPERS ==================
const norm = s => String(s ?? '').trim().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');

// aceita "R$ 12.500,00", 12500, "850,00" etc.
const toNum = v => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[R$\s%]/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
};

const brl = n => n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

// lê campo ignorando maiúsculas/acentos nas chaves
const get = (o, ...nomes) => {
  const alvo = nomes.map(norm);
  for (const k of Object.keys(o || {})) if (alvo.includes(norm(k))) return o[k];
  return undefined;
};

const mdTable = (headers, rows) =>
  [
    '| ' + headers.join(' | ') + ' |',
    '| ' + headers.map(() => '---').join(' | ') + ' |',
    ...rows.map(r => '| ' + r.join(' | ') + ' |'),
  ].join('\n');

// ================== 1) COLETA ==================
const itens = $input.all().map(i => i.json);

let clientesRaw = [];
let produtosRaw = [];

for (const j of itens) {
  const cl = j.body?.clientes ?? j.clientes;
  if (Array.isArray(cl)) clientesRaw.push(...cl);

  if (Array.isArray(j.investimentos)) produtosRaw.push(...j.investimentos);
}

// remove duplicados (caso o Merge repita itens)
const vistos = new Set();
clientesRaw = clientesRaw.filter(c => {
  const k = norm(c.email) + '|' + norm(c.nome);
  if (vistos.has(k)) return false;
  vistos.add(k);
  return true;
});

const vistosP = new Set();
produtosRaw = produtosRaw.filter(p => {
  const k = norm(get(p, 'perfil')) + '|' + norm(get(p, 'produto'));
  if (vistosP.has(k)) return false;
  vistosP.add(k);
  return true;
});

if (!clientesRaw.length) {
  throw new Error('Nenhum cliente em body.clientes. Recebido: ' + JSON.stringify(itens).slice(0, 600));
}
if (!produtosRaw.length) {
  throw new Error('Nenhum produto em "investimentos". Recebido: ' + JSON.stringify(itens).slice(0, 600));
}

// ================== 2) NORMALIZAÇÃO ==================
const clientes = clientesRaw.map(c => ({
  nome: String(c.nome ?? '').trim(),
  email: String(c.email ?? '').trim().toLowerCase(),
  saldo: toNum(c.saldo),
  perfil: String(c.perfil ?? '').trim(),
  perfilKey: norm(c.perfil),
}));

const produtos = produtosRaw.map(p => ({
  perfil: String(get(p, 'perfil') ?? '').trim(),
  perfilKey: norm(get(p, 'perfil')),
  produto: String(get(p, 'produto') ?? '').trim(),
  minimo: toNum(get(p, 'minimo', 'mínimo')),
  rentabilidade: String(get(p, 'rentabilidade') ?? '').trim(),
}));

// ================== 3) CRUZAMENTO + TABELA ==================
const resultados = clientes.map(cli => {
  const doPerfil = produtos.filter(p => p.perfilKey === cli.perfilKey);

  const linhas = doPerfil.map(p => [
    p.produto,
    brl(p.minimo),
    p.rentabilidade,
    cli.saldo >= p.minimo ? 'Sim' : 'Não',
  ]);

  const tabela = doPerfil.length
    ? mdTable(['Produto', 'Mínimo', 'Rentabilidade', 'Saldo suficiente?'], linhas)
    : '(nenhum produto cadastrado para este perfil)';

  const texto =
`Cliente: ${cli.nome}
Email: ${cli.email}
Perfil: ${cli.perfil}
Saldo disponível: ${brl(cli.saldo)}

Produtos do perfil:
${tabela}`;

  return {
    nome: cli.nome,
    email: cli.email,
    perfil: cli.perfil,
    saldo: cli.saldo,
    produtos_elegiveis: doPerfil.filter(p => cli.saldo >= p.minimo).map(p => p.produto),
    tabela_markdown: tabela,
    texto_para_ia: texto,
  };
});

// ================== 4) SAÍDA ==================
if (MODO === 'unico') {
  return [{
    json: {
      total_clientes: resultados.length,
      texto_para_ia: resultados.map(r => r.texto_para_ia).join('\n\n---\n\n'),
      clientes: resultados,
    },
  }];
}
return resultados.map(r => ({ json: r }));

