// ================== CONFIG ==================
const NO_NORMALIZACAO = 'Code in JavaScript1';   // nome EXATO do seu nó de normalização
const ASSUNTO_PADRAO = (primeiroNome) => `${primeiroNome}, veja sugestões de investimento para o seu perfil`;
const ASSINATURA = '';   // ex: '\n\nEquipe de Investimentos' (deixe vazio se a IA já assina)

// ================== HELPERS ==================
const toNum = v => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').replace(/[R$\s%]/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
};
const brl = n => Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// extrai o texto da resposta do nó de IA (aceita vários formatos de saída)
function textoDaIA(j) {
  if (typeof j.text === 'string') return j.text;
  if (typeof j.output === 'string') return j.output;
  if (typeof j.response === 'string') return j.response;
  if (Array.isArray(j.content)) return j.content.map(c => c?.text ?? '').join('\n');
  if (typeof j.content === 'string') return j.content;
  if (j.message?.content) return typeof j.message.content === 'string'
    ? j.message.content
    : j.message.content.map(c => c?.text ?? '').join('\n');
  if (Array.isArray(j.choices)) return j.choices[0]?.message?.content ?? '';
  return '';
}

// lê produtos da tabela markdown (plano B, se o campo "produtos" não existir)
function produtosDaTabela(md, saldo) {
  return String(md || '').split('\n')
    .filter(l => l.trim().startsWith('|'))
    .map(l => l.split('|').slice(1, -1).map(c => c.trim()))
    .filter(c => c.length >= 3 && !/^-+$/.test(c[0]) && c[0].toLowerCase() !== 'produto')
    .map(c => ({
      produto: c[0],
      minimo: toNum(c[1]),
      rentabilidade: c[2],
      saldo_suficiente: c[3] ? /^sim/i.test(c[3]) : saldo >= toNum(c[1]),
    }));
}

// ================== 1) DADOS DO CLIENTE (nó de normalização) ==================
let cli;
try {
  cli = $(NO_NORMALIZACAO).item.json;
} catch (e) {
  cli = $(NO_NORMALIZACAO).all()[$itemIndex]?.json;
}
if (!cli) throw new Error(`Não achei o nó "${NO_NORMALIZACAO}". Confira o nome na constante NO_NORMALIZACAO.`);

// ================== 2) TEXTO GERADO PELA IA ==================
let texto = textoDaIA($json).trim();

// limpa formatações comuns: cercas de código, aspas externas, "ASSUNTO:" / "MENSAGEM:"
texto = texto.replace(/^```[a-z]*\n?|```$/gim, '').trim();
let assuntoIA = '';
const mAss = texto.match(/^\s*assunto\s*:\s*(.+)$/im);
if (mAss) {
  assuntoIA = mAss[1].trim();
  texto = texto.replace(mAss[0], '').trim();
}
texto = texto.replace(/^\s*mensagem\s*:\s*/i, '').trim();
texto = texto.replace(/^["“](.*)["”]$/s, '$1').trim();

// ================== 3) VALIDAÇÃO (evita enviar e-mail quebrado) ==================
let motivo = '';
if (!texto) motivo = 'A IA não devolveu texto.';
else if (/\{\{|\}\}/.test(texto)) motivo = 'O texto contém expressão não resolvida ({{ }}).';
else if (/(preciso (receber|d[ao]s)|n[aã]o consigo (visualizar|localizar)|compartilhe (os|a|as)|n[aã]o foi fornecid)/i.test(texto))
  motivo = 'A IA disse que não recebeu os dados do cliente.';
else if (!cli.email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(cli.email)) motivo = 'E-mail do cliente ausente ou inválido.';

// ================== 4) CAMPOS ESTRUTURADOS ==================
const saldo = toNum(cli.saldo);
const produtos = Array.isArray(cli.produtos) && cli.produtos.length
  ? cli.produtos.map(p => ({ ...p, minimo: toNum(p.minimo) }))
  : produtosDaTabela(cli.tabela_markdown, saldo);

const elegiveis = produtos.filter(p => p.saldo_suficiente);
const principal = elegiveis[0] ?? produtos[0] ?? null;
const primeiroNome = String(cli.nome ?? '').trim().split(/\s+/)[0] || 'Cliente';

const corpo_texto = texto + ASSINATURA;
const corpo_html =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;color:#222">' +
  esc(corpo_texto)
    .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
    .split(/\n{2,}/).map(p => `<p>${p.replace(/\n/g, '<br>')}</p>`).join('') +
  '</div>';

// ================== 5) SAÍDA PARA O NÓ DE E-MAIL ==================
return {
  json: {
    // campos que o nó de e-mail usa
    para: cli.email,
    assunto: assuntoIA || ASSUNTO_PADRAO(primeiroNome),
    corpo_texto,
    corpo_html,

    // dados do cliente
    nome: cli.nome,
    primeiro_nome: primeiroNome,
    perfil: cli.perfil,
    saldo,
    saldo_formatado: brl(saldo),

    // produto em destaque (o primeiro que o saldo permite; se nenhum, o primeiro da lista)
    produto: principal?.produto ?? '',
    valor_minimo: principal?.minimo ?? 0,
    valor_minimo_formatado: principal ? brl(principal.minimo) : '',
    rentabilidade: principal?.rentabilidade ?? '',

    // listas completas
    produtos,
    produtos_elegiveis: elegiveis.map(p => p.produto),

    // controle
    valido: motivo === '',
    motivo_invalido: motivo,
  },
};
